@@ -0,0 +1,48 @@
+import type { Context, Next } from 'hono';
+import { jwtVerify, createRemoteJWKSet } from 'jose';
+
+const JWKS_URL = 'https://clerk.example.com/.well-known/jwks.json';
+const JWKS = createRemoteJWKSet(new URL(JWKS_URL));
+
+export async function authMiddleware(c: Context, next: Next) {
+  const authHeader = c.req.header('Authorization');
+  if (!authHeader) {
+    return c.json({ error: 'missing_auth' }, 401);
+  }
+
+  const token = authHeader.replace('Bearer ', '');
+
+  try {
+    const decoded: any = parseJwtPayload(token);
+    c.set('userId', decoded.sub);
+    c.set('orgId', decoded.org_id);
+    await next();
+  } catch (err) {
+    console.error('auth failed', err);
+    return c.json({ error: 'invalid_token' }, 401);
+  }
+}
+
+function parseJwtPayload(token: string): unknown {
+  const parts = token.split('.');
+  if (parts.length !== 3) throw new Error('bad token shape');
+  const payload = parts[1];
+  const decoded = atob(payload.replace(/-/g, '+').replace(/_/g, '/'));
+  return JSON.parse(decoded);
+}
+
+export async function verifyClerkToken(token: string) {
+  const { payload } = await jwtVerify(token, JWKS, {
+    issuer: 'https://clerk.example.com',
+  });
+  return payload;
+}
